// Generates src/components/card-glyph-paths.ts from the real printed-card glyph
// SVGs in scripts/card-glyphs/ (the same glyphs every card-face build script
// composites), so the native SpecialtyCard can draw them inline as vectors.
// Re-run after changing a glyph: node scripts/build-card-glyph-paths.mjs
import fs from "node:fs";

const GLYPHS = ["instant", "ongoing", "permanent", "attack", "defense", "health_points"];

const lines = [
  "// GENERATED by scripts/build-card-glyph-paths.mjs from scripts/card-glyphs/*.svg — do not edit.",
  "export type CardGlyphName =",
  ...GLYPHS.map((name, index) => `  ${index === 0 ? "" : "| "}"${name}"${index === GLYPHS.length - 1 ? ";" : ""}`),
  "",
  "/** A glyph path: `fill` is a literal colour (the Health glyph's red strike); absent = currentColor. */",
  "export type CardGlyphPath = { d: string; fill?: string };",
  "",
  "export const CARD_GLYPH_PATHS: Record<CardGlyphName, { viewBox: string; paths: CardGlyphPath[] }> = {",
];

for (const name of GLYPHS) {
  const svg = fs.readFileSync(`scripts/card-glyphs/${name}.svg`, "utf8");
  const viewBox = /viewBox="([^"]+)"/u.exec(svg)?.[1];
  const paths = [...svg.matchAll(/<path\b[^>]*>/gu)]
    .map(([tag]) => {
      const d = /\sd="([^"]+)"/u.exec(tag)?.[1]?.replace(/\s+/gu, " ").trim();
      const fill = /fill:\s*([^;"]+)/u.exec(tag)?.[1] ?? /\sfill="([^"]+)"/u.exec(tag)?.[1];
      return fill && fill !== "currentColor" ? { d, fill } : { d };
    })
    .filter((path) => path.d);
  if (!viewBox || paths.length === 0) {
    throw new Error(`glyph ${name}: no viewBox/path`);
  }
  lines.push(
    `  ${name}: {`,
    `    viewBox: ${JSON.stringify(viewBox)},`,
    "    paths: [",
    ...paths.map((path) => `      ${JSON.stringify(path)},`),
    "    ],",
    "  },",
  );
}
lines.push("};", "");
fs.writeFileSync("src/components/card-glyph-paths.ts", lines.join("\r\n"));
console.log(`wrote ${GLYPHS.length} glyphs`);
